"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["60235"],{77363(e){e.exports=JSON.parse('{"id":"F405","slug":"martingale-check","name":"Martingale Check for Discounted Prices","subject":"Quantitative Finance","section":"Quant","topic":"Martingales","level":"Intermediate","aliases":["martingale","fair game","discounted price process","no arbitrage test"],"formula":{"latex":"E^{Q}\\\\left[e^{-rT}S_{T}\\\\right]=S_{0}","also":[],"text":"Under risk-neutral probabilities the expected discounted future price equals today\'s price: e^(-rT) x [q x Su + (1 - q) x Sd] = S0"},"symbols":[{"symbol":"E^Q","meaning":"Expected value under risk-neutral probabilities","unit":"number"},{"symbol":"S_u, S_d","meaning":"Up and down prices","unit":"money"},{"symbol":"q","meaning":"Risk-neutral probability","unit":"percent"},{"symbol":"p","meaning":"Real-world probability","unit":"percent"}],"when_to_use":"Use it to test a price model. A martingale is a fair game: its expected future value equals its current value. Discounted asset prices are martingales under the risk-neutral measure, which is the reason risk-neutral pricing works. Under real-world probabilities the discounted price is usually not a martingale, because investors earn a risk premium.","worked_example":{"problem":"A stock at 100 goes to 120 or 90 in a year. The risk-free rate is 5% and the real-world probability of an up move is 60%. Test the discounted price under both sets of probabilities.","inputs":{"s0":100,"su":120,"sd":90,"r":5,"t":1,"p":60},"steps":[{"label":"Risk-neutral probability of up","working":"(100 x exp(0.05 x 1)-sd) / (120-sd)","value":"50.42%"},{"label":"Expected discounted price, risk-neutral","working":"exp(-0.05 x 1) x (0.504237 x 120+(1-0.504237) x sd)","value":"100.00"},{"label":"Expected discounted price, real-world","working":"exp(-0.05 x 1) x (0.6 x 120+(1-0.6) x sd)","value":"102.73"},{"label":"Real-world expected return (continuous)","working":"ln((0.6 x 120+(1-0.6) x sd) / 100) / 1","value":"7.70%"},{"label":"Risk premium over the risk-free rate","working":"0.076961-0.05","value":"2.70%"}],"answer":"Under the risk-neutral probability of 50.42%, the expected discounted price is 100.00, equal to today\'s 100, so it is a martingale. Under the real-world probability it is 102.73, above 100, because the stock is expected to earn more than the risk-free rate. That excess is the risk premium: 2.70% per year."},"calculator":{"available":true,"inputs":[{"id":"s0","label":"Stock price today","unit":"money","type":"number","default":100,"hint":""},{"id":"su","label":"Price if up","unit":"money","type":"number","default":120,"hint":""},{"id":"sd","label":"Price if down","unit":"money","type":"number","default":90,"hint":""},{"id":"r","label":"Risk-free rate","unit":"%","type":"number","default":5,"hint":""},{"id":"t","label":"Years","unit":"years","type":"number","default":1,"hint":"","min":0.1},{"id":"p","label":"Real-world probability of up","unit":"%","type":"number","default":60,"hint":""}],"checks":[],"steps":[{"id":"q","label":"Risk-neutral probability of up","expr":"(s0*exp(r*t)-sd)/(su-sd)","format":"pct2"},{"id":"eq","label":"Expected discounted price, risk-neutral","expr":"exp(-r*t)*(q*su+(1-q)*sd)","format":"money"},{"id":"ep","label":"Expected discounted price, real-world","expr":"exp(-r*t)*(p*su+(1-p)*sd)","format":"money"},{"id":"mu","label":"Real-world expected return (continuous)","expr":"ln((p*su+(1-p)*sd)/s0)/t","format":"pct2"},{"id":"prem","label":"Risk premium over the risk-free rate","expr":"mu-r","format":"pct2"}],"results":["eq","ep","prem"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"q":0.5042369879200805,"eq":100,"ep":102.73277784607711,"mu":0.0769610411361284,"prem":0.02696104113612839}},"finder":{"finds":"Whether discounted prices are fair games","needs":"Prices in each state, rate, real-world probability"},"related":[{"slug":"risk-neutral-pricing","name":"Risk-Neutral Probability and Pricing"},{"slug":"binomial-option-two-step","name":"Binomial Option Pricing (Two Steps)"},{"slug":"expected-value","name":"Expected Value"}],"related_ids":["F404","F330","F058"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msup><mi>E</mi><mi>Q</mi></msup><mrow><mo fence=\\"true\\">[</mo><msup><mi>e</mi><mrow><mo>\u2212</mo><mi>r</mi><mi>T</mi></mrow></msup><msub><mi>S</mi><mi>T</mi></msub><mo fence=\\"true\\">]</mo></mrow><mo>=</mo><msub><mi>S</mi><mn>0</mn></msub></mrow><annotation encoding=\\"application/x-tex\\">E^{Q}\\\\left[e^{-rT}S_{T}\\\\right]=S_{0}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><msup><mi>E</mi><mi>Q</mi></msup><mrow><mo fence=\\"true\\">[</mo><msup><mi>e</mi><mrow><mo>\u2212</mo><mi>r</mi><mi>T</mi></mrow></msup><msub><mi>S</mi><mi>T</mi></msub><mo fence=\\"true\\">]</mo></mrow></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle E^{Q}\\\\left[e^{-rT}S_{T}\\\\right]</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><msub><mi>S</mi><mn>0</mn></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =S_{0}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"cap-weighted-index","name":"Market-Cap-Weighted Index"},"next":{"slug":"maximum-drawdown","name":"Maximum Drawdown"},"lesson":null,"total":522}')}}]);